/**
 * @mixin @node-red/runtime_flows
 */

/**
 * @typedef Flows
 * @type {object}
 * @property {string} rev - the flow revision identifier
 * @property {Array}  flows - the flow configuration, an array of node configuration objects
 */

/**
 * @typedef Flow
 * @type {object}
 * @property {string} id - the flow identifier
 * @property {string} label - a label for the flow
 * @property {Array}  nodes - an array of node configuration objects
 */

var runtime;
var Mutex = require('async-mutex').Mutex;
const mutex = new Mutex();
const { ChatGoogleGenerativeAI } = require("@langchain/google-genai");
const { HumanMessage, SystemMessage } = require("@langchain/core/messages");
const { ChatMistralAI } = require("@langchain/mistralai");

// helper functions
function detectLoop(flows) {
    const graph = {};
    const nodeMap = {};

    flows.forEach(function (node) {
        nodeMap[node.id] = node;
        graph[node.id] = [];
        if (node.wires) {
            node.wires.forEach(function (outputPorts) {
                outputPorts.forEach(function (targetId) {
                    graph[node.id].push(targetId);
                });
            });
        }
    });

    const visited = new Set();
    const inStack = new Set();
    const stack = [];

    function isAllowedLoopNode(nodeId) {
        const node = nodeMap[nodeId];
        return node && (node.type === "Human Oversight" || node.type === "Judge");
    }

    function dfs(nodeId) {
        visited.add(nodeId);
        inStack.add(nodeId);
        stack.push(nodeId);

        for (const neighbor of (graph[nodeId] || [])) {
            if (!visited.has(neighbor)) {
                if (dfs(neighbor)) return true;
            } else if (inStack.has(neighbor)) {
                const cyclePath = stack.slice(stack.indexOf(neighbor));
                return !cyclePath.some(id => isAllowedLoopNode(id));
            }
        }

        stack.pop();
        inStack.delete(nodeId);
        return false;
    }

    for (const node of flows) {
        if (!visited.has(node.id)) {
            if (dfs(node.id)) return true;
        }
    }

    return false;
}
function hasUnconnectedNodes(flows) {
    const allTargets = new Set();
    const allSources = new Set();

    flows.forEach(function (node) {
        if (node.wires) {
            node.wires.forEach(function (port) {
                port.forEach(function (targetId) {
                    allTargets.add(targetId);
                    allSources.add(node.id);
                });
            });
        }
    });

    return flows.some(function (node) {
        // skip tab nodes and config nodes
        if (node.type === "tab" || node.type === "subflow") return false;
        const hasOutput = allSources.has(node.id);
        const hasInput = allTargets.has(node.id);
        return !hasOutput && !hasInput;
    });
}

function hasDirectOutputToOutput(flows) {
    const outputTypes = ["Custom Output", "Requirements", "UML Class Diagram", "User Story"];


    const nodeMap = {};
    flows.forEach(function (node) {
        nodeMap[node.id] = node;
    });

    return flows.some(function (node) {
        if (!outputTypes.includes(node.type)) return false;
        if (!node.wires) return false;

        return node.wires.some(function (port) {
            return port.some(function (targetId) {
                const target = nodeMap[targetId];
                return target && outputTypes.includes(target.type);
            });
        });
    });
}
function buildGraph(flows) {
    const nodeMap = {};
    const graph = {};
    flows.forEach(function (node) {
        nodeMap[node.id] = node;
        graph[node.id] = [];
        if (node.wires) {
            node.wires.forEach(function (port) {
                port.forEach(function (targetId) {
                    graph[node.id].push(targetId);
                });
            });
        }
    });
    return { nodeMap, graph };
}

function buildLLMs(apiKeys) {
    return {
        gemini: apiKeys.gemini ? new ChatGoogleGenerativeAI({
            apiKey: apiKeys.gemini,
            model: "gemini-2.5-flash-lite",
            maxRetries: 0
        }) : null,
        mistral: apiKeys.mistral ? new ChatMistralAI({
            apiKey: apiKeys.mistral,
            model: "mistral-large-latest",
            maxRetries: 0
        }) : null
    };
}

function getLLM(node, llms, apiKeys) {
    const model = node.model ||
        (apiKeys.gemini ? "gemini-2.5-flash-lite" : null) ||
        (apiKeys.mistral ? "mistral-large-latest" : null);
    if (!model) throw new Error("No API keys set.");
    if (model.startsWith("gemini")) {
        if (!llms.gemini) throw new Error("Gemini API key not set.");
        return llms.gemini;
    }
    if (model.startsWith("mistral")) {
        if (!llms.mistral) throw new Error("Mistral API key not set.");
        return llms.mistral;
    }
    throw new Error("Unknown model: " + model);
}

async function invokeNode(node, input, propagatedInput, llms, apiKeys, log) {
    const stepStart = Date.now();
    const systemPrompt = (node.seedingPrompt || "") +
        (propagatedInput ? "\nThis is the overall goal: " + propagatedInput : "");
    const model = getLLM(node, llms, apiKeys);
    const response = await model.invoke([
        new SystemMessage(systemPrompt),
        new HumanMessage(input)
    ]);
    const stepEnd = Date.now();

    if (log) {
        log.steps.push({
            nodeId: node.id,
            nodeName: node.name || node.type,
            nodeType: node.type,
            model: node.model || "fallback",
            systemPrompt,
            input,
            output: response.content,
            startTime: new Date(stepStart).toISOString(),
            endTime: new Date(stepEnd).toISOString(),
            durationMs: stepEnd - stepStart,
            inputTokens: response.usage_metadata?.input_tokens || null,
            outputTokens: response.usage_metadata?.output_tokens || null,
        });
    }

    return response.content;
}

async function traverseGraph(startId, nodeMap, graph, llms, apiKeys, propagatedInput, log, existingConversation, initialOutput) {
    const MAX_LOOP_ITERATIONS = 3;
    const conversation = [...(existingConversation || [])];
    let currentOutput = initialOutput || (conversation.length > 0
        ? conversation[conversation.length - 1].message
        : "");
    let currentId = startId;
    let iterations = 0;
    let status = "ok";
    let message = "";
    let pausedAtNodeId = null;
    let pausedAtNodeIdReject = null;

    while (currentId) {
        const node = nodeMap[currentId];
        if (!node) break;

        if (node.type === "Human Oversight") {
            pausedAtNodeId = graph[currentId][0];
            pausedAtNodeIdReject = graph[currentId][1];
            break;
        }

        if (!node.seedingPrompt) {
            currentId = graph[currentId][0];
            continue;
        }

        currentOutput = await invokeNode(node, currentOutput, propagatedInput, llms, apiKeys, log);
        conversation.push({ agent: node.name || node.type, message: currentOutput });

        if (node.type === "Judge" && currentOutput.startsWith("REVISE")) {
            currentId = graph[currentId][1];
            iterations++;
            if (iterations === MAX_LOOP_ITERATIONS) {
                status = "warning";
                message += "Max loop iterations reached.\n";
                break;
            }
        } else {
            currentId = graph[currentId][0];
            iterations = 0;
        }
    }

    return { conversation, status, message, pausedAtNodeId, pausedAtNodeIdReject };
}

var api = module.exports = {
    init: function (_runtime) {
        runtime = _runtime;
    },
    /**
    * Gets the current flow configuration
    * @param {Object} opts
    * @param {User} opts.user - the user calling the api
    * @param {Object} opts.req - the request to log (optional)
    * @return {Promise<Flows>} - the active flow configuration
    * @memberof @node-red/runtime_flows
    */
    getFlows: async function (opts) {
        runtime.log.audit({ event: "flows.get" }, opts.req);
        return runtime.flows.getFlows();
    },
    /**
    * Sets the current flow configuration
    * @param {Object} opts
    * @param {User} opts.user - the user calling the api
    * @param {Object} opts.flows - the flow configuration: `{flows: [..], credentials: {}}`
    * @param {Object} opts.deploymentType - the type of deployment - "full", "nodes", "flows", "reload"
    * @param {Object} opts.req - the request to log (optional)
    * @return {Promise<Flows>} - the active flow configuration
    * @memberof @node-red/runtime_flows
    */
    setFlows: async function (opts) {
        return mutex.runExclusive(async function () {
            var flows = opts.flows;
            var deploymentType = opts.deploymentType || "full";
            runtime.log.audit({ event: "flows.set", type: deploymentType }, opts.req);

            var apiPromise;
            if (deploymentType === 'reload') {
                apiPromise = runtime.flows.loadFlows(true);
            } else {
                if (flows.hasOwnProperty('rev')) {
                    var currentVersion = runtime.flows.getFlows().rev;
                    if (currentVersion !== flows.rev) {
                        var err;
                        err = new Error();
                        err.code = "version_mismatch";
                        err.status = 409;
                        //TODO: log warning
                        throw err;
                    }
                }
                apiPromise = runtime.flows.setFlows(flows.flows, flows.credentials, deploymentType, null, null, opts.user);
            }
            return apiPromise.then(function (flowId) {
                return { rev: flowId };
            }).catch(function (err) {
                runtime.log.warn(runtime.log._("api.flows.error-" + (deploymentType === 'reload' ? 'reload' : 'save'), { message: err.message }));
                runtime.log.warn(err.stack);
                throw err
            });
        });
    },


    /**
    * Adds a flow configuration
    * @param {Object} opts
    * @param {User} opts.user - the user calling the api
    * @param {Object} opts.flow - the flow to add
    * @param {Object} opts.req - the request to log (optional)
    * @return {Promise<String>} - the id of the added flow
    * @memberof @node-red/runtime_flows
    */
    addFlow: async function (opts) {
        return mutex.runExclusive(async function () {
            var flow = opts.flow;
            return runtime.flows.addFlow(flow, opts.user).then(function (id) {
                runtime.log.audit({ event: "flow.add", id: id }, opts.req);
                return id;
            }).catch(function (err) {
                runtime.log.audit({
                    event: "flow.add",
                    error: err.code || "unexpected_error",
                    message: err.toString()
                }, opts.req);
                err.status = 400;
                throw err;
            })
        });
    },

    /**
    * Gets an individual flow configuration
    * @param {Object} opts
    * @param {User} opts.user - the user calling the api
    * @param {Object} opts.id - the id of the flow to retrieve
    * @param {Object} opts.req - the request to log (optional)
    * @return {Promise<Flow>} - the active flow configuration
    * @memberof @node-red/runtime_flows
    */
    getFlow: async function (opts) {
        var flow = runtime.flows.getFlow(opts.id);
        if (flow) {
            runtime.log.audit({ event: "flow.get", id: opts.id }, opts.req);
            return flow;
        } else {
            runtime.log.audit({ event: "flow.get", id: opts.id, error: "not_found" }, opts.req);
            var err = new Error();
            err.code = "not_found";
            err.status = 404;
            throw err;
        }
    },
    /**
    * Updates an existing flow configuration
    * @param {Object} opts
    * @param {User} opts.user - the user calling the api
    * @param {Object} opts.id - the id of the flow to update
    * @param {Object} opts.flow - the flow configuration
    * @param {Object} opts.req - the request to log (optional)
    * @return {Promise<String>} - the id of the updated flow
    * @memberof @node-red/runtime_flows
    */
    updateFlow: async function (opts) {
        return mutex.runExclusive(async function () {
            var flow = opts.flow;
            var id = opts.id;
            return runtime.flows.updateFlow(id, flow, opts.user).then(function () {
                runtime.log.audit({ event: "flow.update", id: id }, opts.req);
                return id;
            }).catch(function (err) {
                if (err.code === 404) {
                    runtime.log.audit({ event: "flow.update", id: id, error: "not_found" }, opts.req);
                    // TODO: this swap around of .code and .status isn't ideal
                    err.status = 404;
                    err.code = "not_found";
                } else {
                    runtime.log.audit({
                        event: "flow.update",
                        error: err.code || "unexpected_error",
                        message: err.toString()
                    }, opts.req);
                    err.status = 400;
                }
                throw err;
            })
        });
    },
    /**
    * Deletes a flow
    * @param {Object} opts
    * @param {User} opts.user - the user calling the api
    * @param {Object} opts.id - the id of the flow to delete
    * @param {Object} opts.req - the request to log (optional)
    * @return {Promise} - resolves if successful
    * @memberof @node-red/runtime_flows
    */
    deleteFlow: async function (opts) {
        return mutex.runExclusive(function () {
            var id = opts.id;
            return runtime.flows.removeFlow(id, opts.user).then(function () {
                runtime.log.audit({ event: "flow.remove", id: id }, opts.req);
                return;
            }).catch(function (err) {
                if (err.code === 404) {
                    runtime.log.audit({ event: "flow.remove", id: id, error: "not_found" }, opts.req);
                    // TODO: this swap around of .code and .status isn't ideal
                    err.status = 404;
                    err.code = "not_found";
                } else {
                    runtime.log.audit({
                        event: "flow.remove",
                        id: id,
                        error: err.code || "unexpected_error",
                        message: err.toString()
                    }, opts.req);
                    err.status = 400;
                }
                throw err;
            });
        });
    },

    /**
    * Gets the safe credentials for a node
    * @param {Object} opts
    * @param {User} opts.user - the user calling the api
    * @param {String} opts.type - the node type to return the credential information for
    * @param {String} opts.id - the node id
    * @param {Object} opts.req - the request to log (optional)
    * @return {Promise<Object>} - the safe credentials
    * @memberof @node-red/runtime_flows
    */
    getNodeCredentials: async function (opts) {
        runtime.log.audit({ event: "credentials.get", type: opts.type, id: opts.id }, opts.req);
        var credentials = runtime.nodes.getCredentials(opts.id);
        if (!credentials) {
            return {};
        }
        var sendCredentials = {};
        var cred;
        if (/^subflow(:|$)/.test(opts.type) ||
            (opts.type === "tab") ||
            (opts.type === "group")) {
            for (cred in credentials) {
                if (credentials.hasOwnProperty(cred)) {
                    sendCredentials['has_' + cred] = credentials[cred] != null && credentials[cred] !== '';
                }
            }
        } else {
            var definition = runtime.nodes.getCredentialDefinition(opts.type) || {};
            for (cred in definition) {
                if (definition.hasOwnProperty(cred)) {
                    if (definition[cred].type == "password") {
                        var key = 'has_' + cred;
                        sendCredentials[key] = credentials[cred] != null && credentials[cred] !== '';
                        continue;
                    }
                    sendCredentials[cred] = credentials[cred] || '';
                }
            }
        }
        return sendCredentials;
    },
    /**
    * Gets running state of runtime flows
    * @param {Object} opts
    * @param {User} opts.user - the user calling the api
    * @param {Object} opts.req - the request to log (optional)
    * @return {{state:string, started:boolean}} - the current run state of the flows
    * @memberof @node-red/runtime_flows
    */
    getState: async function (opts) {
        runtime.log.audit({ event: "flows.getState" }, opts.req);
        const result = {
            state: runtime.flows.state()
        }
        return result;
    },
    /**
    * Sets running state of runtime flows
    * @param {Object} opts
    * @param {Object} opts.req - the request to log (optional)
    * @param {User} opts.user - the user calling the api
    * @param {string} opts.state - the requested state. Valid values are "start" and "stop".
    * @return {Promise<Flow>} - the active flow configuration
    * @memberof @node-red/runtime_flows
    */
    setState: async function (opts) {
        opts = opts || {};
        const makeError = (error, errcode, statusCode) => {
            const message = typeof error == "object" ? error.message : error
            const err = typeof error == "object" ? error : new Error(message || "Unexpected Error")
            err.status = err.status || statusCode || 400;
            err.code = err.code || errcode || "unexpected_error"
            runtime.log.audit({
                event: "flows.setState",
                state: opts.state || "",
                error: errcode || "unexpected_error",
                message: err.code
            }, opts.req);
            return err
        }

        const getState = () => {
            return {
                state: runtime.flows.state()
            }
        }

        if (!runtime.settings.runtimeState || runtime.settings.runtimeState.enabled !== true) {
            throw (makeError("Method Not Allowed", "not_allowed", 405))
        }
        switch (opts.state) {
            case "start":
                try {
                    try {
                        runtime.settings.set('runtimeFlowState', opts.state);
                    } catch (err) { }
                    if (runtime.settings.safeMode) {
                        delete runtime.settings.safeMode
                    }
                    await runtime.flows.startFlows("full")
                    return getState()
                } catch (err) {
                    throw (makeError(err, err.code, 500))
                }
            case "stop":
                try {
                    try {
                        runtime.settings.set('runtimeFlowState', opts.state);
                    } catch (err) { }
                    await runtime.flows.stopFlows("full")
                    return getState()
                } catch (err) {
                    throw (makeError(err, err.code, 500))
                }
            default:
                throw (makeError(`Cannot change flows runtime state to '${opts.state}'}`, "invalid_run_state", 400))
        }
    },

    /**
 * Executes the current workflow
 * @param {Object} opts
 * @param {User} opts.user - the user calling the api
 * @param {Array} opts.flows - the flow configuration to execute
 * @param {Object} opts.req - the request to log (optional)
 * @return {Promise<Object>} - the execution result
 * @memberof @node-red/runtime_flows
 */

    executeWorkflow: async function (opts) {
        runtime.log.audit({ event: "flows.execute" }, opts.req);
        try {
            var status = "ok";
            var message = "";
            const startTime = Date.now();

            const log = {
                startTime: new Date().toISOString(),
                endTime: null,
                durationMs: null,
                workflow: {
                    nodes: opts.flows.flows
                        .filter(n => n.type !== "tab")
                        .map(n => ({
                            id: n.id,
                            type: n.type,
                            name: n.name || n.type,
                            model: n.model || null,
                            seedingPrompt: n.seedingPrompt || null,
                            wires: n.wires || []
                        })),
                    edges: opts.flows.flows
                        .filter(n => n.wires)
                        .flatMap(n => n.wires.flatMap(port => port.map(targetId => ({
                            from: n.id,
                            fromName: n.name || n.type,
                            to: targetId
                        }))))
                },
                steps: [],
                warnings: [],
                apiKeysUsed: {
                    gemini: !!opts.apiKeys.gemini,
                    mistral: !!opts.apiKeys.mistral
                }
            };

            const inputNodes = opts.flows.flows.filter(n => n.type === "Text Input");
            if (inputNodes.length !== 1)
                return { status: "error", message: "Wrong amount of input nodes, one is required." };

            if (detectLoop(opts.flows.flows))
                return { status: "error", message: "Flow contains a loop without HITL or judge agent to escape it." };

            if (hasDirectOutputToOutput(opts.flows.flows)) {
                status = "warning";
                message += "Chain of output nodes in the workflow.\n";
                log.warnings.push("Chain of output nodes in the workflow.");
            }

            if (hasUnconnectedNodes(opts.flows.flows)) {
                status = "warning";
                message += "Unconnected nodes in the workflow.\n";
                log.warnings.push("Unconnected nodes in the workflow.");
            }

            const containsHITL = opts.flows.flows.some(n => n.type === "Human Oversight");
            const llms = buildLLMs(opts.apiKeys);
            const { nodeMap, graph } = buildGraph(opts.flows.flows);

            const startNode = opts.flows.flows.find(n => n.type === "Text Input");
            if (!startNode) return { status: "error", message: "No Text Input node found." };

            const propagatedInput = startNode.propagate ? startNode.text : null;

            log.steps.push({
                nodeId: startNode.id,
                nodeName: startNode.name || "Text Input",
                nodeType: "Text Input",
                model: null,
                input: null,
                output: startNode.text || "",
                startTime: new Date().toISOString(),
                endTime: new Date().toISOString(),
                durationMs: 0
            });

            const firstNodeId = graph[startNode.id][0];
            const result = await traverseGraph(firstNodeId, nodeMap, graph, llms, opts.apiKeys, propagatedInput, log, [], startNode.text);

            if (result.status === "warning") { status = "warning"; message += result.message; }

            log.endTime = new Date().toISOString();
            log.durationMs = Date.now() - startTime;

            return {
                status,
                message,
                HITL: containsHITL,
                hitlNodeId: result.pausedAtNodeId,
                hitlNodeIdReject: result.pausedAtNodeIdReject,
                conversation: result.conversation,
                log
            };

        } catch (err) {
            return { status: "error", message: err.message };
        }
    },

    // ─── resumeWorkflow ────────────────────────────────────────────────────────────

    resumeWorkflow: async function (opts) {
        runtime.log.audit({ event: "flows.resume" }, opts.req);
        try {
            const startTime = Date.now();

            status = "ok"
            message = ""
            if (!opts.resumeFromNodeId) return { status: "error", message: "resumeFromNodeId is required." };
            if (!opts.previousConversation) return { status: "error", message: "previousConversation is required." };

            const log = opts.previousLog ? {
                ...opts.previousLog,
                resumeCount: (opts.previousLog.resumeCount || 0) + 1,
                steps: [...opts.previousLog.steps]
            } : {
                startTime: new Date().toISOString(),
                steps: [],
                warnings: [],
                resumeCount: 1
            };

            log.steps.push({
                nodeId: "human",
                nodeName: "Human",
                nodeType: "Human Oversight",
                model: null,
                input: null,
                output: opts.humanInput ? "✗ Rejected: " + opts.humanInput : "✓ Accepted",
                decision: opts.humanInput ? "rejected" : "accepted",
                feedback: opts.humanInput || null,
                startTime: new Date().toISOString(),
                endTime: new Date().toISOString(),
                durationMs: 0
            });

            const containsHITL = opts.flows.flows.some(n => n.type === "Human Oversight");
            const llms = buildLLMs(opts.apiKeys);
            const { nodeMap, graph } = buildGraph(opts.flows.flows);

            const startNode = opts.flows.flows.find(n => n.type === "Text Input");
            const propagatedInput = startNode?.propagate ? startNode.text : null;

            // inject human input as last conversation entry
            const lastAgentMessage = opts.previousConversation
                .filter(e => e.agent !== "Human")
                .slice(-1)[0]?.message || "";

            const previousConversation = opts.humanInput
                ? [
                    ...opts.previousConversation,
                    {
                        agent: "Human",
                        message: "Feedback: " + opts.humanInput + "\n\nPrevious output to revise:\n" + lastAgentMessage
                    }
                ]
                : [...opts.previousConversation];

            const result = await traverseGraph(
                opts.resumeFromNodeId,
                nodeMap,
                graph,
                llms,
                opts.apiKeys,
                propagatedInput,
                log,
                previousConversation
            );

            log.endTime = new Date().toISOString();
            log.durationMs = Date.now() - startTime;

            return {
                status,
                message,
                HITL: containsHITL,
                hitlNodeId: result.pausedAtNodeId,
                hitlNodeIdReject: result.pausedAtNodeIdReject,
                conversation: result.conversation,
                log
            };

        } catch (err) {
            return { status: "error", message: err.message };
        }
    },
}
